def isMajorityElement(nums, target):
    # Helper to find first index ≥ x
    def lower_bound(array, x):
        left, right = 0, len(array)
        while left < right:
            mid = (left + right) // 2
            if array[mid] < x:
                left = mid + 1
            else:
                right = mid
        return left

    # Helper to find first index > x
    def upper_bound(array, x):
        left, right = 0, len(array)
        while left < right:
            mid = (left + right) // 2
            if array[mid] <= x:
                left = mid + 1
            else:
                right = mid
        return left

    n = len(nums)
    first = lower_bound(nums, target)
    last = upper_bound(nums, target)
    count = last - first

    return count > n // 2
